"""Build Voxel's small original bitmap-outline TrueType font; no dependencies."""
import struct as st
from pathlib import Path
P={
'A':'01110/10001/10001/11111/10001/10001/10001','B':'11110/10001/10001/11110/10001/10001/11110','C':'01111/10000/10000/10000/10000/10000/01111','D':'11110/10001/10001/10001/10001/10001/11110','E':'11111/10000/10000/11110/10000/10000/11111','F':'11111/10000/10000/11110/10000/10000/10000','G':'01111/10000/10000/10111/10001/10001/01110','H':'10001/10001/10001/11111/10001/10001/10001','I':'111/010/010/010/010/010/111','J':'00111/00010/00010/00010/10010/10010/01100','K':'10001/10010/10100/11000/10100/10010/10001','L':'10000/10000/10000/10000/10000/10000/11111','M':'10001/11011/10101/10101/10001/10001/10001','N':'10001/11001/10101/10011/10001/10001/10001','O':'01110/10001/10001/10001/10001/10001/01110','P':'11110/10001/10001/11110/10000/10000/10000','Q':'01110/10001/10001/10001/10101/10010/01101','R':'11110/10001/10001/11110/10100/10010/10001','S':'01111/10000/10000/01110/00001/00001/11110','T':'11111/00100/00100/00100/00100/00100/00100','U':'10001/10001/10001/10001/10001/10001/01110','V':'10001/10001/10001/10001/10001/01010/00100','W':'10001/10001/10001/10101/10101/11011/10001','X':'10001/10001/01010/00100/01010/10001/10001','Y':'10001/10001/01010/00100/00100/00100/00100','Z':'11111/00001/00010/00100/01000/10000/11111',
'0':'01110/10011/10101/10101/11001/10001/01110','1':'010/110/010/010/010/010/111','2':'01110/10001/00001/00010/00100/01000/11111','3':'11110/00001/00001/01110/00001/00001/11110','4':'00010/00110/01010/10010/11111/00010/00010','5':'11111/10000/10000/11110/00001/00001/11110','6':'01110/10000/10000/11110/10001/10001/01110','7':'11111/00001/00010/00100/01000/01000/01000','8':'01110/10001/10001/01110/10001/10001/01110','9':'01110/10001/10001/01111/00001/00001/01110',
'.':'0/0/0/0/0/0/1',',':'00/00/00/00/00/01/10',':':'0/1/0/0/1/0/0',';':'00/01/00/00/01/01/10','!':'1/1/1/1/1/0/1','?':'01110/10001/00001/00010/00100/00000/00100','-':'00000/00000/00000/11111/00000/00000/00000','+':'00000/00100/00100/11111/00100/00100/00000','/':'00001/00001/00010/00100/01000/10000/10000','%':'11001/11010/00100/00100/01000/10110/00110','(':'001/010/100/100/100/010/001',')':'100/010/001/001/001/010/100','[':'111/100/100/100/100/100/111',']':'111/001/001/001/001/001/111','=':'00000/00000/11111/00000/11111/00000/00000','_':'00000/00000/00000/00000/00000/00000/11111',"'":'1/1/0/0/0/0/0','"':'101/101/000/000/000/000/000','&':'01100/10010/10100/01000/10101/10010/01101','<':'0001/0010/0100/1000/0100/0010/0001','>':'1000/0100/0010/0001/0010/0100/1000','|':'1/1/1/1/1/1/1',
'←':'00000/00100/01000/11111/01000/00100/00000','→':'00000/00100/00010/11111/00010/00100/00000','↑':'00100/01110/10101/00100/00100/00100/00100','✓':'00000/00001/00001/10010/10100/01000/00000','●':'00000/01110/11111/11111/11111/01110/00000','○':'00000/01110/10001/10001/10001/01110/00000','·':'0/0/0/1/0/0/0','↗':'11111/00011/00101/01001/10001/00000/00000','↻':'01110/10001/00011/00111/00001/10001/01110',' ':''}
for c in 'abcdefghijklmnopqrstuvwxyz':P[c]=P[c.upper()]
for c,alias in {'’':"'",'‘':"'",'“':'"','”':'"','–':'-','—':'-','×':'X'}.items():P[c]=P[alias]
u16=lambda n:st.pack('>H',n&65535)
i16=lambda n:st.pack('>h',n)
u32=lambda n:st.pack('>I',n&0xffffffff)
pad=lambda b:b+b'\0'*((-len(b))%4)
chars=sorted(P,key=ord);patterns=[P['?']]+[P[c] for c in chars]
glyf=b'';loca=[];widths=[]
for pattern in patterns:
 loca.append(len(glyf));points=[];ends=[]
 rows=pattern.split('/') if pattern else []
 for y,row in enumerate(rows):
  for x,value in enumerate(row):
   if value!='1':continue
   a=(x*100,(6-y)*100);points.extend([a,(a[0],a[1]+100),(a[0]+100,a[1]+100),(a[0]+100,a[1])]);ends.append(len(points)-1)
 count=len(ends);w=max(map(len,rows),default=3)*100;widths.append(w+100)
 data=i16(count)+i16(0)+i16(0)+i16(w)+i16(700 if count else 0)
 if count:
  data+=b''.join(u16(n) for n in ends)+u16(0)+bytes([1]*len(points));last=0
  for x,y in points:data+=i16(x-last);last=x
  last=0
  for x,y in points:data+=i16(y-last);last=y
 glyf+=pad(data)
loca.append(len(glyf));num=len(patterns)
tables={'glyf':glyf,'loca':b''.join(u32(n) for n in loca),'hmtx':b''.join(u16(w)+i16(0) for w in widths)}
tables['head']=st.pack('>IIIIHHQQhhhhHHhhh',0x10000,0x10000,0,0x5f0f3cf5,3,800,0,0,0,0,600,700,0,8,2,1,0)
tables['hhea']=u32(0x10000)+b''.join(i16(n) for n in [800,-200,0,600,0,0,600,1,0,0,0,0,0,0,0,num])
tables['maxp']=u32(0x10000)+u16(num)+b''.join(u16(n) for n in [140,35,0,0,2,0,0,0,0,0,0,0,0])
tables['post']=st.pack('>IIhhIIIII',0x30000,0,-75,50,0,0,0,0,0)
os2=u16(0)+i16(600)+u16(400)+u16(5)+u16(0)+b''.join(i16(n) for n in [650,600,0,75,650,600,0,350,50,250,0])+bytes([2,11,6,9,2,2,2,2,2,4])+u32(1)+u32(0)+u32(0)+u32(0)+b'VOXL'+u16(0x40)+u16(32)+u16(max(map(ord,chars)))+i16(800)+i16(-200)+i16(0)+u16(800)+u16(200)
tables['OS/2']=os2
codes=[ord(c) for c in chars]+[65535];n=len(codes);power=2**(n.bit_length()-1)
sub=u16(4)+u16(16+8*n)+u16(0)+u16(2*n)+u16(2*power)+u16(power.bit_length()-1)+u16(2*n-2*power)
sub+=b''.join(u16(c) for c in codes)+u16(0)+b''.join(u16(c) for c in codes)+b''.join(u16(i+1-c) for i,c in enumerate(codes[:-1]))+u16(1)+b'\0\0'*n
tables['cmap']=u16(0)+u16(1)+u16(3)+u16(1)+u32(12)+sub
names={1:'Voxel Pixel',2:'Regular',3:'VoxelPixel2026',4:'Voxel Pixel Regular',5:'Version 1.0',6:'VoxelPixel-Regular'};records=b'';strings=b''
for key,value in names.items():
 encoded=value.encode('utf-16-be');records+=u16(3)+u16(1)+u16(0x409)+u16(key)+u16(len(encoded))+u16(len(strings));strings+=encoded
tables['name']=u16(0)+u16(len(names))+u16(6+12*len(names))+records+strings
def checksum(data):return sum(st.unpack('>'+str(len(pad(data))//4)+'I',pad(data)))&0xffffffff
keys=sorted(tables);n=len(keys);power=2**(n.bit_length()-1);directory=u32(0x10000)+u16(n)+u16(16*power)+u16(power.bit_length()-1)+u16(16*n-16*power);body=b'';offset=12+16*n;head_offset=0
for key in keys:
 data=tables[key];directory+=key.encode()+u32(checksum(data))+u32(offset)+u32(len(data))
 if key=='head':head_offset=offset
 body+=pad(data);offset+=len(pad(data))
font=bytearray(directory+body);font[head_offset+8:head_offset+12]=u32(0xb1b0afba-checksum(bytes(font)))
out=Path(__file__).resolve().parents[1]/'assets'/'voxel-pixel.ttf';out.parent.mkdir(exist_ok=True);out.write_bytes(font)
print(out.name,len(font),'bytes',num,'glyphs')
